const seasons = $input.first().json;
const list = Array.isArray(seasons) ? seasons : (seasons.body || seasons.data || []);
const current = list.find(s => s.current) || list[0];
const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Helsinki' }));
const dd = String(now.getDate()).padStart(2,'0');
const mm = String(now.getMonth()+1).padStart(2,'0');
const yyyy = now.getFullYear();
const iso = `${yyyy}-${mm}-${dd}`;
const fi = `${dd}.${mm}.${yyyy}`;
const end = new Date(now); end.setDate(end.getDate()+10);
const edd = String(end.getDate()).padStart(2,'0');
const emm = String(end.getMonth()+1).padStart(2,'0');
const eyyyy = end.getFullYear();
return [{
  json: {
    season: current.SeasonNumber,
    seasonName: current.SeasonName,
    assId: '11015646',
    dateIso: iso,
    dateFi: fi,
    endFi: `${edd}.${emm}.${eyyyy}`
  }
}];

const meta = $('Päiväys ja kausi').first().json;
const games = $input.first().json;
const list = Array.isArray(games) ? games : [];
function statusOf(g) {
  if ((g.FinishedType || 0) >= 1) return 'finished';
  if (g.GameStatus === 1) return 'live';
  if (g.GameStatus === 2 || g.GameStatus === 94) return 'finished';
  return 'upcoming';
}
const today = list.filter(g => g.GameDate === meta.dateFi).map(g => ({
  game_id: g.GameID,
  date: g.GameDate,
  time: (g.GameTime || '').slice(0,5),
  status: statusOf(g),
  level: g.LevelName,
  rink: g.RinkName || g.RinkAbbrv,
  venue: String(g.HomeAssociation) === String(meta.assId) ? 'home' : 'away',
  home: { abbreviation: g.HomeAbbrv, goals: g.HomeGoals, association_id: g.HomeAssociation },
  away: { abbreviation: g.AwayAbbrv, goals: g.AwayGoals, association_id: g.AwayAssociation },
  score: statusOf(g) === 'finished' ? `${g.HomeGoals}-${g.AwayGoals}` : null,
  urls: { gamecentre: `https://tulospalvelu.leijonat.fi/game?gameid=${g.GameID}` }
}));
const payload = {
  generated_at: new Date().toISOString(),
  date: meta.dateIso,
  date_fi: meta.dateFi,
  club: { id: meta.assId, name: 'SISU HOCKEY HÄMEENLINNA RY', abbreviation: 'SiSu' },
  season: { number: meta.season, name: meta.seasonName },
  counts: {
    total: today.length,
    upcoming: today.filter(g => g.status === 'upcoming').length,
    live: today.filter(g => g.status === 'live').length,
    finished: today.filter(g => g.status === 'finished').length
  },
  games: today
};
return [{ json: { payload, content: JSON.stringify(payload, null, 2) } }];
